import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let $a, b, c, p$ be positive integers satisfying the equation $c = (a+bi)^3 - {m}(p+pi) - {K}i$, where $i^2=-1$. Find the sum of all possible values of $c$ for which $a+b < {S}$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
from math import sqrt

n = 3 # Power is fixed to 3

while True:
    m = rng.choice([3, 4, 5, 6, 7, 8, 9, 10])
    S = rng.randint(15, 25)

    # Pre-calculate potential (a,b) pairs to seed K
    candidate_pairs = []
    for b_seed in range(1, S):
        for a_seed in range(1, S - b_seed):
            if 3 * a_seed**2 - b_seed**2 > 0:
                candidate_pairs.append((a_seed, b_seed))

    if not candidate_pairs:
        continue

    rng.shuffle(candidate_pairs)

    for a0, b0 in candidate_pairs:
        X0 = b0 * (3 * a0**2 - b0**2)

        # c = a^3 - 3ab^2 - 3a^2b + b^3 + K
        c_without_K = a0**3 - 3*a0*b0**2 - 3*a0**2*b0 + b0**3

        # We need K > -c_without_K for c > 0
        # We need K < X0 for p > 0
        min_K = -c_without_K + 1
        max_K = X0 - 1

        if min_K > max_K:
            continue

        # Find possible K values
        # K must satisfy K % m == X0 % m
        rem = X0 % m

        # Start from a value >= min_K that has the correct remainder
        k_start = min_K
        if k_start % m != rem:
            k_start += (rem - (k_start % m) + m) % m

        possible_K = [k for k in range(k_start, max_K + 1, m) if k > 0]

        if not possible_K:
            continue

        K = rng.choice(possible_K)

        # Verify this choice of (m, K, S) yields a good problem
        solutions_c = set()
        for b_sol in range(1, S):
            for a_sol in range(1, S - b_sol):
                if 3 * a_sol**2 - b_sol**2 <= 0:
                    continue

                X = b_sol * (3 * a_sol**2 - b_sol**2)

                if X > K and (X - K) % m == 0:
                    # p is a positive integer
                    c = a_sol**3 - 3*a_sol*b_sol**2 - 3*a_sol**2*b_sol + b_sol**3 + K
                    if c > 0:
                        solutions_c.add(c)

        if 2 <= len(solutions_c) <= 10:
            return {
                'm': m,
                'K': K,
                'S': S
            }

